from pathlib import Path
from collections import OrderedDict,Counter
import json,ast,statistics
root=Path(Path('/tmp/photonic-membership-root').read_text())
def load(path):
    run=[]; event=[]
    for line in path.read_text().splitlines():
        part=line.split()
        if part[0]=='begin':
            if event:run.append(event)
            event=[];continue
        if part[0]=='touch':event.append(('touch',int(part[1]),tuple(ast.literal_eval(line.split(' ',2)[2]))));continue
        event.append(tuple([part[0]]+[True if p=='true' else False if p=='false' else int(p) for p in part[1:]]))
    if event:run.append(event)
    for index, value in enumerate(run):
        normalized=[]; touch=[]
        for item in value:
            if item[0]=='touch':touch.append(item);continue
            normalized.extend(sorted(touch));touch=[];normalized.append(item)
        normalized.extend(sorted(touch));run[index]=normalized
    assert len(run)==2 and run[0]==run[1],path
    return run[0]
def simulate(event,capacity,unused):
    cache=OrderedDict();active={};generation=0;full=False;frame=0
    count=Counter();gap=Counter();size=[];touch={};weight=[]
    for e in event:
        if e[0]=='update':
            generation=e[1];touch={}
            size.append(len(cache));weight.append(sum(v['weight'] for v in cache.values()))
        elif e[0]=='touch':
            frame,input=e[1:];touch[frame]=set(input)
            count['maintenance']+=sum(k[0]==frame and k[1] in touch[frame] for k in cache)
        elif e[0]=='frame':
            frame,full=e[1:]
            if full:
                removed=[k for k in cache if k[0]==frame]
                for key in removed:del cache[key]
                count['invalidation']+=len(removed)
        elif e[0]=='visit':
            active[e[1]]['visit']=True
        elif e[0]=='insert':
            frame,input,owner,position,viable,retained=e[1:];key=(frame,input,owner)
            if generation:count['admission']+=1
            if key in cache:
                record=cache.pop(key);count['hit']+=1;gap[generation-record['generation']]+=1
                count['visited_hit']+=record['visit'];count['viable_hit']+=viable
            active[position]={'visit':False,'key':key,'start':generation}
        elif e[0]=='remove':
            frame,input,owner,position,enabled,present,retained=e[1:];key=(frame,input,owner)
            record=active.pop(position);assert record['key']==key
            if not full and present and not enabled:
                count['eligible']+=1
                if capacity and (not unused or not record['visit']):
                    record.update(generation=generation,weight=retained)
                    cache[key]=record
                    count['stored']+=1
                    count['maintenance']+=input in touch.get(frame,set())
                    if len(cache)>capacity:cache.popitem(last=False);count['eviction']+=1
        else:raise ValueError(e)
    return {'capacity':capacity,'unused':unused,**count,'remaining':len(cache),'maximum':max(size),'mean':statistics.mean(size),'weight_maximum':max(weight),'weight_mean':statistics.mean(weight),'gap':dict(sorted(gap.items()))}
artifact=[]
for path in sorted(root.glob('*.trace')):
    event=load(path)
    value={'name':path.stem,'identical':2,'event':len(event),'policy':[]}
    for unused in [False,True]:
        for capacity in [0,8,16,32,64,128,256,512,1024,1000000]:
            result=simulate(event,capacity,unused);value['policy'].append(result)
            if capacity in [32,128,1000000]:print(path.stem,result,flush=True)
    artifact.append(value)
(root/'simulation.json').write_text(json.dumps(artifact,indent=2)+'\n')

